INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4872193', 'Battle of Roatán', 'The Battle of Roatán (sometimes spelled "Rattan") was an American War of Independence battle fought on March 16, 1782, between British and Spanish forces for control of Roatán, an island off the Caribbean coast of present-day Honduras. A Spanish expeditionary force under Matías de Gálvez, the Captain General of Spanish Guatemala, gained control of the British-held island after bombarding its main defences.', 1782, 3, 16, NULL, NULL, NULL, 'day', '16 March 1782', 34, 'https://en.wikipedia.org/wiki/Battle_of_Roat%C3%A1n'),
  ('Q17633452', 'First Central American Civil War', 'The First Central American Civil War (Spanish: Primera Guerra Civil Centroamericana), also known as the Federal War of 1826–1829 (Guerra Federal de 1826–1829), was a civil political and military conflict within the Federal Republic of Central America which lasted from 1826 until 1829. The civil war was fought between liberals led by General Francisco Morazán and conservatives led by General Manuel José Arce, the president of Central America and a former liberal.', 1826, 9, 6, 1829, 6, 25, 'day', '6 September 1826 – 25 June 1829', 37, 'https://en.wikipedia.org/wiki/First_Central_American_Civil_War'),
  ('Q17462627', '1827 Honduran coup d''état', 'The 1827 Honduran coup d''état was a military takeover of the Honduran government under Dionisio de Herrera, initiated on April 4 by the then Lieutenant General José Justo Milla. The first constitution of Honduras, dated 11 December 1825, established four-year terms for the head of state, with Herrera''s initial term to end on 16 September 1827.', 1827, NULL, NULL, NULL, NULL, NULL, 'year', '1827', 26, 'https://en.wikipedia.org/wiki/1827_Honduran_coup_d''%C3%A9tat'),
  ('Q2890498', 'Battle of La Arada', 'The Battle of La Arada (Spanish: Batalla de la Arada) was fought on 2 February 1851 near the town of Chiquimula in Guatemala, between the forces of Guatemala and an Allied army from Honduras and El Salvador. As the most serious threat to Guatemala''s liberty and sovereignty as a republic, it was the most important military victory in the country''s history as an independent state.', 1851, 2, 2, NULL, NULL, NULL, 'day', '2 February 1851', 34, 'https://en.wikipedia.org/wiki/Battle_of_La_Arada'),
  ('Q5835762', 'Guerra de los Padres', 'The Guerra de los Padres ("War of the Priests") was a violent political crisis that took place in Honduras between April and June 1861. A conflict between the government and the clergy began when president José Santos Guardiola agreed to permit freedom of worship to the inhabitants of the Bay Islands, a predominantly Protestant colony of Britain.', 1861, NULL, NULL, NULL, NULL, NULL, 'year', '1861', 26, 'https://en.wikipedia.org/wiki/Guerra_de_los_Padres'),
  ('Q5918797', 'Barrios'' War of Reunification', 'Barrios'' War of Reunification, also known as Barrios'' great attempt (Spanish: intentona de Barrios), was a war initiated by Guatemalan President Justo Rufino Barrios in 1885 with the goal of reunifying Central America. Of the five Central American countries, only Honduras supported Barrios'' reunification effort; Costa Rica, El Salvador, and Nicaragua opposed it, as did Mexico.', 1885, 2, 28, 1885, 4, 14, 'day', '28 February 1885 – 14 April 1885', 26, 'https://en.wikipedia.org/wiki/Barrios''_War_of_Reunification'),
  ('Q6086281', 'First Honduran Civil War', 'The First Honduran Civil War (Spanish: Primera guerra civil hondureña) or the Revolution of 19 (Spanish: Revolución del 19) was an armed conflict that took place in the Republic of Honduras in 1919. This was the first conflict in Honduran soil where the weapons and technological advances of the 20th century were felt.', 1919, 7, 23, 1919, 9, 17, 'day', '23 July 1919 – 17 September 1919', 34, 'https://en.wikipedia.org/wiki/First_Honduran_Civil_War'),
  ('Q6123725', 'Second Honduran Civil War', 'The Second Honduran Civil War (Spanish: Segunda guerra civil hondureña), also known as the Reclamation Revolution (Spanish: Revolución Reivindicatoria), was a civil war that took place in Honduras in 1924. This was the first conflict in Honduras where airplanes were used for aerial bombardment, and new war tactics inherited from the First World War were employed.', 1924, 2, 2, 1924, 5, 1, 'day', '2 February 1924 – 1 May 1924', 30, 'https://en.wikipedia.org/wiki/Second_Honduran_Civil_War'),
  ('Q773999', 'Convention for the Suppression of the Traffic in Persons and of the Exploitation of the Prostitution of Others', 'The Convention for the Suppression of the Traffic in Persons and of the Exploitation of the Prostitution of Others was approved by the United Nations General Assembly on 2 December 1949 and entered into force on 25 July 1951. The preamble states: Whereas prostitution and the accompanying evil of the traffic in persons for the purpose of prostitution are incompatible with the dignity and worth of the human person and endanger the welfare of the individual, the family, and the community.', 1950, 3, 21, NULL, NULL, NULL, 'day', '21 March 1950', 56, 'https://en.wikipedia.org/wiki/Convention_for_the_Suppression_of_the_Traffic_in_Persons_and_of_the_Exploitation_of_the_Prostitution_of_Others'),
  ('Q4571109', '1963 Honduran coup d''état', 'A coup d''état took place in Honduras on 3 October 1963, ten days before a scheduled election. Oswaldo López Arellano replaced Ramón Villeda Morales as president and initiated two decades of military rule.', 1963, 10, 3, NULL, NULL, NULL, 'day', '3 October 1963', 37, 'https://en.wikipedia.org/wiki/1963_Honduran_coup_d''%C3%A9tat'),
  ('Q223085', 'Hundred Hour War', 'The Football War (Spanish: guerra del fútbol), also known as the Soccer War or the 100 Hour War, was a brief military conflict fought between El Salvador and Honduras in 1969. Existing tensions between the two countries coincided with rioting during a 1970 FIFA World Cup qualifier, hence its nickname.', 1969, 7, 14, 1969, 7, 18, 'day', '14 July 1969 – 18 July 1969', 75, 'https://en.wikipedia.org/wiki/Football_War'),
  ('Q4576634', '1975 Honduran coup d''état', 'The 1975 Honduran coup d''état took place on 22 April 1975, with Oswaldo López Arellano being ousted in a military coup led by his fellow General Juan Alberto Melgar Castro. The coup was prompted in part by the "Bananagate" scandal, exposed by the U.S. Securities and Exchange Commission in 1975, in which the United Brands Company agreed to bribe President López with US$1.25 million, and the promise of another $1.25 million upon the reduction of certain banana export taxes.', 1975, 4, 22, NULL, NULL, NULL, 'day', '22 April 1975', 30, 'https://en.wikipedia.org/wiki/1975_Honduran_coup_d''%C3%A9tat'),
  ('Q7682001', 'Tan-Sahsa Flight 414', 'TAN-SAHSA Flight 414 was a scheduled flight from Juan Santamaría International Airport, San José, Costa Rica, to Toncontín Airport in Tegucigalpa, Honduras, with a stopover at Augusto C. Sandino Airport in Managua, Nicaragua, on 21 October 1989. Flown with a Boeing 727-200, the flight crashed into a mountain at 7:30 A.M. local time after the pilots failed to follow a special landing procedure required for the arrival to the airport.', 1989, 10, 21, NULL, NULL, NULL, 'day', '21 October 1989', 48, 'https://en.wikipedia.org/wiki/TAN-SAHSA_Flight_414'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q7888366', 'United Nations Convention on the Use of Electronic Communications in International Contracts', 'The United Nations Convention on the Use of Electronic Communications in International Contracts (the "Electronic Communications Convention", ECC or e-cc) is a treaty that aims at facilitating the use of electronic communications in international trade. It was prepared by the United Nations Commission on International Trade Law (UNCITRAL) and adopted by the United Nations General Assembly on 23 November 2005.', 2005, 11, 23, NULL, NULL, NULL, 'day', '23 November 2005', 41, 'https://en.wikipedia.org/wiki/Electronic_Communications_Convention'),
  ('Q4261830', 'TACA Flight 390', 'TACA Flight 390 was a scheduled flight on May 30, 2008, by TACA International from San Salvador, El Salvador, to Miami, Florida, United States, with intermediate stops at Tegucigalpa and San Pedro Sula in Honduras. The aircraft, an Airbus A320, overran the runway after landing at Tegucigalpa''s Toncontín International Airport and rolled out into a street, crashing into an embankment and smashing several cars in the process.', 2008, 5, 30, NULL, NULL, NULL, 'day', '30 May 2008', 48, 'https://en.wikipedia.org/wiki/TACA_Flight_390'),
  ('Q1073488', '2009 Honduran coup d''état', 'The 2009 Honduran coup d''état occurred during the 2009 Honduran constitutional crisis. It was triggered after President Manuel Zelaya refused to comply with a Honduran Supreme Court ruling.', 2009, 6, 28, NULL, NULL, NULL, 'day', '28 June 2009', 56, 'https://en.wikipedia.org/wiki/2009_Honduran_coup_d''%C3%A9tat'),
  ('Q4613958', '2009 Honduras earthquake', 'The 2009 Swan Islands earthquake occurred on May 28 at 02:24:45 AM local time with a moment magnitude of 7.3 and a maximum Mercalli intensity of VII (Very strong). The epicenter was located in the Caribbean Sea, 64 kilometres (40 mi) northeast of the island of Roatán, 19 miles northeast of Port Royal, Isla de Bahias, 15 miles northwest of Isla Barbaretta, and 130 kilometres (81 mi) north-northeast of La Ceiba.', 2009, 5, 28, NULL, NULL, NULL, 'day', '28 May 2009', 34, 'https://en.wikipedia.org/wiki/2009_Swan_Islands_earthquake'),
  ('Q1368313', 'Comayagua prison fire', 'A deadly fire occurred on 14–15 February 2012 at the National Penitentiary in Comayagua, Honduras, killing 361 people. Prisoners trapped in their cells died by burning or suffocation; dozens were burned beyond recognition.', 2012, 2, 14, NULL, NULL, NULL, 'day', '14 February 2012', 45, 'https://en.wikipedia.org/wiki/Comayagua_prison_fire'),
  ('Q47161142', '2018 Swan Islands earthquake', 'On 9 January 2018, at approximately 8:51 p.m. local time (02:51:10 January UTC), a magnitude 7.5 earthquake struck in the Yucatán Basin of the Caribbean Sea, 44 kilometres (27 mi) east of Great Swan Island off the coast of Honduras.', 2018, 1, 9, NULL, NULL, NULL, 'day', '9 January 2018', 45, 'https://en.wikipedia.org/wiki/2018_Swan_Islands_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q115628162', 'Honduran gang crackdown (2022–present)', 'The Honduran gang crackdown, referred to in Honduras as the Régimen de Excepción (Spanish for State of Exception), began in December 2022 after parts of the constitution were suspended to fight criminal gangs in the country. Initially instituted for forty-five days in two municipalities, Tegucigalpa and San Pedro Sula, the state of exception has been renewed and extended to more than half of the country''s cities.', 2022, 12, 6, NULL, NULL, NULL, 'day', '6 December 2022', 34, 'https://en.wikipedia.org/wiki/Honduran_gang_crackdown');
